SELECT ST_Area_Spheroid(
         ST_Convex_Hull(
           ST_Collect(
             list(
               ST_Point(s.longitude, s.latitude)
               ORDER BY s.station_id
             )
           )
         )::GEOMETRY
       ) / 1e6 AS area_km2
FROM ghcn_stations s
WHERE s.country_code = 'BR'

SELECT ST_Length_Spheroid(
         ST_Boundary(
           ST_ConvexHull(
             ST_Collect(
               list(ST_Point(longitude, latitude)::GEOMETRY)
             )
           )
         )
       ) / 1000.0 AS perimeter_km
FROM ghcn_stations
WHERE country_code = 'AS'

