WITH d AS (
  SELECT geom FROM fr_departements WHERE nom = 'Ardennes'
), b AS (
  SELECT ST_Buffer(ST_Centroid(geom), 20000) AS geom FROM d
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM b;

WITH d AS (
  SELECT geom FROM fr_departements WHERE nom IN ('Landes', 'Pyrénées-Orientales')
), u AS (
  SELECT ST_Union_Agg(geom) AS geom FROM d
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM u;

WITH city AS (
  SELECT ST_Transform(ST_Point(2.1905, 41.4099), 'EPSG:4326', 'EPSG:32631', always_xy := true) AS geom
), dept AS (
  SELECT ST_Transform(geom, 'EPSG:2154', 'EPSG:32631', always_xy := true) AS geom
  FROM fr_departements WHERE nom = 'Pyrénées-Orientales'
), inter AS (
  SELECT ST_Intersection(d.geom, ST_Buffer(c.geom, 200000)) AS geom
  FROM dept d, city c
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM inter;

WITH d AS (
  SELECT geom FROM fr_departements WHERE nom = 'Landes'
), b AS (
  SELECT ST_Buffer(ST_Centroid(geom), 25000) AS geom FROM d
), diff AS (
  SELECT ST_Difference(d.geom, b.geom) AS geom FROM d, b
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM diff;

WITH d AS (
  SELECT geom FROM fr_departements WHERE nom IN ('Ardennes', 'Meurthe-et-Moselle', 'Tarn-et-Garonne')
), hull AS (
  SELECT ST_ConvexHull(ST_Union_Agg(geom)) AS geom FROM d
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM hull;

WITH pemalang AS (
  SELECT ST_Transform(ST_Point(109.3826, -6.8919), 'EPSG:4326', 'EPSG:32749', always_xy := true) AS geom
), cities AS (
  SELECT geonameid, ST_Transform(geometry, 'EPSG:4326', 'EPSG:32749', always_xy := true) AS geom
  FROM geonames_cities
  WHERE country_code = 'ID' AND admin1_code = '07'
), buf AS (
  SELECT ST_Buffer(geom, 100000) AS geom FROM pemalang
)
SELECT COUNT(*) AS city_count
FROM cities, buf
WHERE ST_Intersects(cities.geom, buf.geom)
  AND cities.geonameid <> 1631648;
